src = src.replace('def merge_cfg(uid:Optional[int]=None)->Dict[str,Any]:\n    base=dict(CFG)\n    if uid is not None:\n        u=user_cfg(uid)\n        for k,v in u.items():\n            if not k.startswith("_") and k in base:\n                base[k]=v\n    return base\n', 'def merge_cfg(uid:Optional[int]=None)->Dict[str,Any]:\n    base=dict(CFG)\n    if uid is not None:\n        u=user_cfg(uid)\n        for k,v in u.items():\n            if not k.startswith("_") and k in base:\n                base[k]=v\n    for k in ("ban_all","kick_instead","timeout_instead","skip_bots","skip_owner","webhook_spam","ping_everyone","delete_channels","delete_roles","delete_emojis","delete_stickers","rename_server","mass_nick","mass_dm","create_channels","spam_after_create","nsfw_channels","hoist_roles","admin_role"):\n        if k in base: base[k]=_as_bool(base[k])\n    for k in ("spam_channels","spam_messages","create_roles","create_voice","create_cats","create_stage","create_forum","timeout_days","delay_sec"):\n        if k in base: base[k]=_as_int(base[k], 0)\n    if "spam_messages" in base: base["spam_messages"]=max(1, min(50, int(base["spam_messages"] or 1)))\n    if "spam_channels" in base: base["spam_channels"]=max(0, min(100, int(base["spam_channels"] or 0)))\n    return base\n')
